export const FILM_PRESETS=[
['short','Phim ngắn','Short film','A cinematic short film with a clear beginning, development and ending.'],
['tvc','TVC ngắn','Short TVC','A concise TV commercial with a strong opening hook, product benefit, visual proof and final brand hold.'],
['ad','Quảng cáo','Advertising','A persuasive brand film focused on one message, credible product use and clear call-to-action space.'],
['fashion','Thời trang','Fashion','A fashion editorial film. Preserve outfit, fabric, fit and model identity. Emphasize silhouette, controlled posing and fabric motion.'],
['beauty','Mỹ phẩm','Cosmetics','A beauty film with authentic skin texture, precise packaging, material detail and natural application. No unsubstantiated medical or before/after claims.'],
['product','Sản phẩm','Product','A product showcase preserving exact geometry, labels and materials. Mix hero, macro and practical use shots.'],
['animation','Hoạt hình','Animation','An animated story with consistent character design, shape language and a unified rendering style.'],
['food','Ẩm thực','Food','A food film emphasizing preparation, texture, appetizing light and plausible movement.'],
['interior','Không gian','Interiors','An architectural film preserving spatial continuity, proportions, materials and plausible camera movement.'],
['social','Video mạng xã hội','Social video','A mobile-first social film with an immediate hook, concise visual beats and a clear ending.'],
['music','Video âm nhạc','Music video','A visual music film with recurring motifs, coherent mood and rhythmic editing; use only authorized audio.'],
['series','Phim dài tập','Series','An episodic story with a shared character bible, recurring settings, continuity and a clear arc for each episode.']];
export function filmBrief(id,lang='vi'){const p=FILM_PRESETS.find(p=>p[0]===id)||FILM_PRESETS[0];return lang==='en'?`FORMAT: ${p[2]}\nDIRECTION: ${p[3]}\nSTORY / MESSAGE: \nCHARACTERS / PRODUCT: \nLOCATION: \nVISUAL STYLE: \nOPENING → DEVELOPMENT → ENDING: \nDIALOGUE / SOUND: \nCONTINUITY: Preserve identities, wardrobe, materials and lighting between scenes.\nSCENES: Each generated clip is at most 10 seconds; plan longer films as connected clips.`:`THỂ LOẠI: ${p[1]}\nĐỊNH HƯỚNG: ${({'short':'Câu chuyện điện ảnh có mở đầu, phát triển và kết thúc.','tvc':'Mở đầu thu hút → lợi ích → minh họa → giữ hình thương hiệu.','ad':'Một thông điệp chính, tình huống sử dụng và kết thúc rõ ràng.','fashion':'Giữ nhân vật, trang phục; nhấn phom dáng và chuyển động vải.','beauty':'Da tự nhiên, bao bì chính xác, thao tác sử dụng hợp lý.','product':'Giữ hình dáng, nhãn, chất liệu; xen cảnh toàn và chi tiết.','animation':'Giữ thiết kế nhân vật và phong cách kết xuất xuyên suốt.','food':'Chất liệu món ăn, quy trình chế biến và ánh sáng hấp dẫn.','interior':'Giữ kết cấu không gian, tỷ lệ và đường di chuyển máy.','social':'Mở đầu nhanh, nhịp ngắn, kết thúc dễ hiểu.','music':'Mô-típ thị giác lặp lại, nhịp dựng phù hợp; dùng âm thanh có quyền sử dụng.','series':'Hồ sơ nhân vật chung, bối cảnh lặp lại và mạch truyện từng tập.'})[p[0]]}\nCÂU CHUYỆN / THÔNG ĐIỆP: \nNHÂN VẬT / SẢN PHẨM: \nBỐI CẢNH: \nPHONG CÁCH: \nMỞ ĐẦU → PHÁT TRIỂN → KẾT THÚC: \nTHOẠI / ÂM THANH: \nNHẤT QUÁN: Giữ nhân vật, trang phục, chất liệu và ánh sáng giữa các cảnh.\nPHÂN CẢNH: Mỗi đoạn tạo tối đa 10 giây; phim dài gồm các đoạn nối tiếp.`}
